//! A very small re-implementation of the `terminal_size` crate.
//!
//! Only the pieces required by the argument parser's help renderer are
//! provided: the `Width`/`Height` newtypes and `terminal_size()`.
//!
//! The terminal size is looked up on the standard output first, then on the
//! standard error and finally on the standard input.

use std::os::unix::io::RawFd;

/// The width of a terminal in cells.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Width(pub u16);

/// The height of a terminal in cells.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Height(pub u16);

const TIOCGWINSZ: libc_ulong = 0x5413;

#[allow(non_camel_case_types)]
type libc_ulong = std::os::raw::c_ulong;

#[repr(C)]
#[derive(Default)]
#[allow(non_camel_case_types)]
struct winsize {
    ws_row: std::os::raw::c_ushort,
    ws_col: std::os::raw::c_ushort,
    ws_xpixel: std::os::raw::c_ushort,
    ws_ypixel: std::os::raw::c_ushort,
}

extern "C" {
    fn ioctl(fd: RawFd, request: libc_ulong, ...) -> std::os::raw::c_int;
}

/// Retrieves the size of the terminal the process is attached to.
///
/// The standard output, standard error and standard input are probed in that
/// order, returning `None` when none of them is a terminal.
pub fn terminal_size() -> Option<(Width, Height)> {
    const STDOUT: RawFd = 1;
    const STDERR: RawFd = 2;
    const STDIN: RawFd = 0;

    for fd in [STDOUT, STDERR, STDIN] {
        if let Some(size) = size_of_fd(fd) {
            return Some(size);
        }
    }

    None
}

fn size_of_fd(fd: RawFd) -> Option<(Width, Height)> {
    let mut size = winsize::default();

    let res = unsafe { ioctl(fd, TIOCGWINSZ, &mut size as *mut winsize) };

    if res == -1 {
        return None;
    }

    if size.ws_row > 0 && size.ws_col > 0 {
        Some((Width(size.ws_col), Height(size.ws_row)))
    } else {
        None
    }
}
EOF
