s=open(p).read()
s = s.replace('[[bin]]', '''[patch.crates-io]
terminal_size = { path = "vendor/terminal_size" }

[[bin]]''')
open(p,'w').write(s)
EOF
cat Cargo.toml && cargo build --offline 2>&1 | tail -5"}

