/// A single reference to an issue that a commit closes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Issue {
    /// The issue number, exactly as it appeared in the commit message.
    pub issue: String,
    /// The rendered link pointing at the issue.
    pub issue_link: String,
}

/// A commit that has been matched against a section.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Commit {
    pub component: Option<String>,
    pub subject: String,
    pub hash: String,
    pub closes: Option<Vec<Issue>>,
    pub breaks: Option<Vec<Issue>>,
}

impl Commit {
    /// Returns the number that should be used to identify this commit in the
    /// rendered changelog.
    pub fn short_hash(&self) -> &str {
        &self.hash[..8]
    }
}

/// A group of commits sharing the same component.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Section {
    pub title: String,
    pub commits: Vec<Commit>,
}

/// A commit as it comes out of `git log`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RawCommit {
    pub hash: String,
    pub subject: String,
    pub body: String,
}

/// Splits the `git log` output into individual commits.
pub fn parse_log(output: &str) -> Vec<RawCommit> {
    let mut commits = Vec::new();
    let mut lines = output.lines();

    while let Some(hash) = lines.next() {
        let Some(subject) = lines.next() else { break };

        let mut body = Vec::new();

        loop {
            match lines.next() {
                Some(line) if line == COMMIT_END => break,
                Some(line) => body.push(line),
                None => break,
            }
        }

        commits.push(RawCommit {
            hash: hash.to_string(),
            subject: subject.to_string(),
            body: body.join("\n"),
        });
    }

    commits
}

/// Tries to interpret the subject of a commit as a `alias(component): message`
/// or `alias: message` reference of the given section.
///
/// Returns the component together with the remaining subject, or `None` when
/// the subject does not belong to this section.
pub fn match_subject(subject: &str, aliases: &[String]) -> Option<(Option<String>, String)> {
    for alias in aliases {
        if !subject.starts_with(alias.as_str()) || alias.len() >= subject.len() {
            continue;
        }

        let rest = &subject[alias.len()..];

        if let Some(rest) = rest.strip_prefix('(') {
            let Some(end) = rest.find(')') else { continue };

            let component = &rest[..end];
            let rest = &rest[end + 1..];

            let Some(rest) = rest.strip_prefix(':') else { continue };

            let component = if component.is_empty() {
                None
            } else {
                Some(component.to_string())
            };

            return Some((component, rest.trim_end().to_string()));
        }

        if let Some(rest) = rest.strip_prefix(':') {
            return Some((None, rest.trim_end().to_string()));
        }
    }

    None
}

/// Collects every `Closes #N` reference found in the body of a commit.
pub fn parse_issues(body: &str) -> Vec<Issue> {
    body.lines()
        .filter_map(|line| first_issue(line))
        .map(|issue| Issue {
            issue_link: issue.to_string(),
            issue,
        })
        .collect()
}

/// Finds the first `Closes #N` reference of a single line, honouring the comma
/// separated list form where the last entry of the list is kept.
fn first_issue(line: &str) -> Option<String> {
    const KEY: &str = "Closes #";

    let mut idx = 0;

    while let Some(found) = line[idx..].find(KEY) {
        let start = idx + found + KEY.len();
        let Some(first) = take_digits(&line[start..]) else {
            idx = start;
            continue;
        };

        let mut best = first;
        let mut pos = start + first.len();

        while let Some((next, len)) = take_list_entry(&line[pos..]) {
            best = next;
            pos += len;
        }

        return Some(best.to_string());
    }

    None
}

fn take_digits(s: &str) -> Option<&str> {
    let end = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());

    if end == 0 { None } else { Some(&s[..end]) }
}

/// Matches a single `, #N` continuation of a `Closes` reference, returning the
/// number together with the number of bytes it consumed.
fn take_list_entry(s: &str) -> Option<(&str, usize)> {
    let mut idx = 0;
    let mut chars = s.chars();

    if chars.next()? != ',' {
        return None;
    }
    idx += 1;

    if !chars.next()?.is_whitespace() {
        return None;
    }
    idx += s[idx..].chars().next().unwrap().len_utf8();

    if chars.next()? != '#' {
        return None;
    }
    idx += 1;

    let digits = take_digits(&s[idx..])?;

    Some((digits, idx + digits.len()))
}

/// Groups the raw commits into the sections described by `sections`.
///
/// Commits that do not belong to any section are silently dropped. Inside a
/// section the commits are grouped by their component, which also determines
/// the order in which they are written out.
pub fn build_sections(commits: &[RawCommit], sections: &[(String, Vec<String>)]) -> Vec<Section> {
    let mut out = Vec::new();

    for (title, aliases) in sections {
        let mut grouped: BTreeMap<Option<String>, Vec<Commit>> = BTreeMap::new();

        for raw in commits {
            let Some((component, subject)) = match_subject(&raw.subject, aliases) else { continue };

            let issues = parse_issues(&raw.body);
            let closes = if issues.is_empty() { None } else { Some(issues.clone()) };
            let breaks = if raw.body.contains("BREAKING") { Some(issues) } else { None };

            grouped.entry(component).or_default().push(Commit {
                component,
                subject,
                hash: raw.hash.clone(),
                closes,
                breaks,
            });
        }

        if grouped.is_empty() {
            continue;
        }

        out.push(Section {
            title: title.clone(),
            commits: grouped.into_values().flatten().collect(),
        });
    }

    out
}
