use semver::Version;

use crate::errors::Error;

/// The version that is written into the changelog header.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VersionInfo {
    /// The version as it should be rendered, `None` when unknown.
    pub version: Option<String>,
    /// Whether the release only bumped the patch level.
    pub patch_version: bool,
}

/// Figures out the version of the release that is being documented.
///
/// `--setversion` always wins, otherwise the bump flags are applied to the
/// version found on the latest tag.
pub fn resolve(setversion: Option<String>, bump: Option<Bump>, tag: Option<&str>) -> Result<VersionInfo, Error> {
    if let Some(set) = setversion {
        return Ok(VersionInfo { version: Some(set), patch_version: false });
    }

    let Some(bump) = bump else {
        return Ok(VersionInfo { version: None, patch_version: false });
    };

    let Some(tag) = tag else {
        return Err(Error::SemVer);
    };

    let (prefix, rest) = split_prefix(tag);
    let mut parsed = Version::parse(rest).map_err(|_| Error::SemVer)?;

    match bump {
        Bump::Major => {
            parsed.major += 1;
            parsed.minor = 0;
            parsed.patch = 0;
        }
        Bump::Minor => {
            parsed.minor += 1;
            parsed.patch = 0;
        }
        Bump::Patch => {
            parsed.patch += 1;
        }
    }

    Ok(VersionInfo {
        version: Some(format!("{prefix}{parsed}")),
        patch_version: matches!(bump, Bump::Patch),
    })
}

/// Splits a leading `v`/`V` marker away from the version number itself.
fn split_prefix(tag: &str) -> (&'static str, &str) {
    let rest = tag.trim_start_matches(|c| c == 'v' || c == 'V');

    if rest.len() == tag.len() {
        ("", tag)
    } else {
        ("v", rest)
    }
}

/// Which part of the version should be incremented.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Bump {
    Major,
    Minor,
    Patch,
}

impl Bump {
    /// Returns the bump that was requested on the command line.
    ///
    /// The flags are mutually exclusive in practice, the strongest one wins.
    pub fn from_flags(major: bool, minor: bool, patch: bool) -> Option<Bump> {
        if major {
            Some(Bump::Major)
        } else if minor {
            Some(Bump::Minor)
        } else if patch {
            Some(Bump::Patch)
        } else {
            None
        }
    }
}
EOF
echo ok"}

