pub mod json_writer;
pub mod md_writer;

use std::io::Write;

use crate::errors::Error;

/// Where the rendered changelog ends up.
pub enum Sink {
    /// The changelog is printed to the standard output.
    Stdout,
    /// The changelog is written into a file, which is truncated on open.
    File(std::fs::File),
}

impl Sink {
    /// Opens the sink for the given output file, or falls back to stdout.
    pub fn new(outfile: Option<&str>) -> Result<Sink, Error> {
        match outfile {
            Some(path) => {
                let file = std::fs::File::create(path).map_err(|_| Error::Io)?;

                Ok(Sink::File(file))
            }
            None => Ok(Sink::Stdout),
        }
    }

    /// Appends a chunk of text to the sink.
    pub fn write(&mut self, text: &str) -> Result<(), Error> {
        match self {
            Sink::Stdout => {
                print!("{text}");

                Ok(())
            }
            Sink::File(file) => file.write_all(text.as_bytes()).map_err(|_| Error::Io),
        }
    }
}

/// Everything that is common to the markdown and JSON renderers.
pub struct Header {
    pub version: Option<String>,
    pub patch_version: bool,
    pub subtitle: Option<String>,
    pub date: String,
}
EOF
cat > src/fmt/md_writer.rs <<'EOF'
use crate::fmt::{Header, Sink};
use crate::link_style::LinkStyle;
use crate::section::{Commit, Section};

/// Renders the changelog in markdown format.
pub fn write(header: &Header, sections: &[Section], repository: Option<&str>, style: LinkStyle, sink: &mut Sink) -> Result<(), crate::errors::Error> {
    write_header(header, sink)?;
    write_sections(sections, repository, style, sink)
}

fn write_header(header: &Header, sink: &mut Sink) -> Result<(), crate::errors::Error> {
    let version = header.version.as_deref().unwrap_or("");
    let subtitle = header.subtitle.as_deref().unwrap_or("");
    let level = if header.patch_version { "###" } else { "##" };

    sink.write(&format!("<a name=\"{version}\"></a>\n"))?;
    sink.write(&format!("{level} {version} {subtitle} ({})\n", header.date))?;
    sink.write("\n")
}

fn write_sections(sections: &[Section], repository: Option<&str>, style: LinkStyle, sink: &mut Sink) -> Result<(), crate::errors::Error> {
    for section in sections {
        sink.write(&format!("\n#### {}\n\n", section.title))?;

        let mut idx = 0;

        while idx < section.commits.len() {
            let commit = &section.commits[idx];

            match &commit.component {
                Some(component) => {
                    let mut next = idx + 1;

                    while next < section.commits.len()
                        && section.commits[next].component.as_deref() == Some(component.as_str())
                    {
                        next += 1;
                    }

                    if next - idx > 1 {
                        sink.write(&format!("* **{component}:**\n"))?;

                        for commit in &section.commits[idx..next] {
                            write_entry(sink, "  * ", commit, repository, style)?;
                        }

                        idx = next;
                        continue;
                    }

                    sink.write(&format!("* **{component}:**"))?;
                    write_entry(sink, " ", commit, repository, style)?;
                }
                None => {
                    sink.write("* ")?;
                    write_entry(sink, " ", commit, repository, style)?;
                }
            }

            idx += 1;
        }
    }

    Ok(())
}

fn write_entry(sink: &mut Sink, prefix: &str, commit: &Commit, repository: Option<&str>, style: LinkStyle) -> Result<(), crate::errors::Error> {
    let mut line = String::from(prefix);
    line.push_str(&commit.subject);
    line.push(' ');
    line.push_str(&link(commit, repository, style));
    line.push('\n');

    sink.write(&line)
}

fn link(commit: &Commit, repository: Option<&str>, style: LinkStyle) -> String {
    let mut out = format!("({})", &commit.hash[..8]);

    if repository.is_some() || true {
        let target = style.commit_link(repository, &commit.hash);
        out = format!("({target}");
    }

    if let Some(closes) = &commit.closes {
        for (idx, issue) in closes.iter().enumerate() {
            if idx == 0 {
                out.push_str(", closes ");
            } else {
                out.push_str(", ");
            }

            out.push_str(&format!("[#{0}]({1})", issue.issue, style.issue_link(repository, &issue.issue_link)));
        }
    }

    out.push(')');

    out
}
