            Sink::Stdout => {
                print!("{text}");

                Ok(())
            }
            Sink::File(file) => file.write_all(text.as_bytes()).map_err(|_| Error::Io),
        }
    }
}

/// Everything that is common to the markdown and JSON renderers.
