use crate::fmt::{Header, Sink};
use crate::link_style::LinkStyle;
use crate::section::{Commit, Issue, Section};

/// Renders the changelog as JSON.
///
/// The output is written in a single chunk without a trailing newline, just
/// like the original tool does.
pub fn write(
    header: &Header,
    sections: &[Section],
    repository: Option<&str>,
    style: LinkStyle,
    sink: &mut Sink,
) -> Result<(), crate::errors::Error> {
    let mut out = String::new();

    out.push_str("{\"header\":{\"version\":");
    out.push_str(&version(&header.version));
    out.push_str(",\"patch_version\":");
    out.push_str(if header.patch_version { "true" } else { "false" });
    out.push_str(",\"subtitle\":");
    out.push_str(&subtitle(&header.subtitle));
    out.push_str(&format!(",\"date\":{}", crate::fmt::quote(&header.date)));
    out.push_str("},\"sections\":");

    if sections.is_empty() {
        out.push_str("null");
    } else {
        out.push('[');

        for (idx, section) in sections.iter().enumerate() {
            if idx > 0 {
                out.push(',');
            }

            out.push_str(&format!(
                "{{\"title\":{},\"commits\":[",
                crate::fmt::quote(&section.title)
            ));

            for (idx, commit) in section.commits.iter().enumerate() {
                if idx > 0 {
                    out.push(',');
                }

                write_commit(&mut out, commit, repository, style);
            }

            out.push_str("]}");
        }

        out.push(']');
    }

    out.push('}');

    sink.write(&out)
}

fn version(version: &Option<String>) -> String {
    match version {
        Some(v) => format!("Some({})", crate::fmt::quote(v)),
        None => "None".to_string(),
    }
}

fn subtitle(subtitle: &Option<String>) -> String {
    match subtitle {
        Some(v) => v.clone(),
        None => "null".to_string(),
    }
}

fn write_commit(out: &mut String, commit: &Commit, repository: Option<&str>, style: LinkStyle) {
    let component = match &commit.component {
        Some(c) => crate::fmt::quote(c),
        None => "null".to_string(),
    };

    out.push_str(&format!("{{\"component\":{component},"));

    let link = style.commit_link(repository, &commit.hash);

    out.push_str(&format!(
        "\"subject\":{},\"commit_link\":{},",
        crate::fmt::quote(&commit.subject),
        crate::fmt::quote(&link)
    ));

    out.push_str(&format!("\"closes\":{},", issues(&commit.closes, repository, style)));
    out.push_str(&format!("\"breaks\":{}}}", issues(&commit.breaks, repository, style)));
}

fn issues(list: &Option<Vec<Issue>>, repository: Option<&str>, style: LinkStyle) -> String {
    let Some(list) = list else {
        return "null".to_string();
