use serde::Deserialize;

use crate::errors::Error;
use crate::link_style::LinkStyle;

/// The `[clog]` table of the configuration file.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "kebab-case", default)]
pub struct ClogConfig {
    pub repository: Option<String>,
    pub from_latest_tag: Option<bool>,
    pub subtitle: Option<String>,
    pub outfile: Option<String>,
    pub changelog: Option<String>,
    pub infile: Option<String>,
    pub git_dir: Option<String>,
    pub link_style: Option<LinkStyle>,
}

impl Default for ClogConfig {
    fn default() -> Self {
        Self {
            repository: None,
            from_latest_tag: None,
            subtitle: None,
            outfile: None,
            changelog: None,
            infile: None,
            git_dir: None,
            link_style: None,
        }
    }
}

/// The whole configuration file.
#[derive(Debug, Clone, Deserialize)]
pub struct ClogToml {
    pub clog: ClogConfig,

    #[serde(rename = "sections")]
    pub sections: Option<toml::Value>,
}

impl ClogToml {
    /// Reads and parses the configuration file at `path`.
    pub fn from_path(path: &str) -> Result<Self, Error> {
        let contents = std::fs::read_to_string(path).map_err(|_| Error::Io)?;

        toml::from_str(&contents).map_err(|_| Error::Toml)
    }

    /// Extracts the `[sections]` table, keeping the order in which the
    /// sections were declared.
    pub fn sections(&self) -> Result<Vec<(String, Vec<String>)>, Error> {
        let Some(value) = &self.sections else {
            return Ok(Vec::new());
        };

        let Some(table) = value.as_table() else {
            return Err(Error::Toml);
        };

        let mut sections = Vec::new();

        for (title, value) in table {
            let Some(array) = value.as_array() else {
                return Err(Error::Toml);
            };

            let mut aliases = Vec::new();

            for item in array {
                let Some(alias) = item.as_str() else {
                    return Err(Error::Toml);
                };

                aliases.push(alias.to_string());
            }

            sections.push((title.clone(), aliases));
        }

        Ok(sections)
    }
}
