    /// Reads and parses the configuration file at `path`.
    pub fn from_path(path: &str) -> Result<Self, Error> {
        let contents = std::fs::read_to_string(path).map_err(|_| Error::Io)?;

        toml::from_str(&contents).map_err(|_| Error::Toml)
    }

    /// Extracts the `[sections]` table, keeping the order in which the
    /// sections were declared.
    pub fn sections(&self) -> Result<Vec<(String, Vec<String>)>, Error> {
        let Some(value) = &self.sections else {
            return Ok(Vec::new());
