    match sink {
        Sink::Buffer(out) => out,
        _ => String::new(),
    }
}

/// Writes the changelog in markdown format to `sink`.
pub fn write(
    header: &Header,
    sections: &[Section],
    repository: Option<&str>,
    style: LinkStyle,
    sink: &mut Sink,
) -> Result<(), crate::errors::Error> {
    write_header(header, sink)?;
    write_sections(sections, repository, style, sink)
}

fn write_header(header: &Header, sink: &mut Sink) -> Result<(), crate::errors::Error> {
    let version = header.version.as_deref().unwrap_or("");
    let subtitle = header.subtitle.as_deref().unwrap_or("");
    let level = if header.patch_version { "###" } else { "##" };

    sink.write(&format!("<a name=\"{version}\"></a>\n"))?;
    sink.write(&format!("{level} {version} {subtitle} ({})\n", header.date))?;
    sink.write("\n")
}

fn write_sections(
    sections: &[Section],
    repository: Option<&str>,
    style: LinkStyle,
    sink: &mut Sink,
) -> Result<(), crate::errors::Error> {
    for section in sections {
        sink.write(&format!("\n#### {}\n\n", section.title))?;

        let mut idx = 0;

        while idx < section.commits.len() {
            let component = section.commits[idx].component.clone();

            let Some(component) = component else {
                sink.write(&entry("* ", " ", &section.commits[idx], repository, style))?;
                idx += 1;
                continue;
            };

            let mut next = idx + 1;

            while next < section.commits.len()
                && section.commits[next].component.as_deref() == Some(component.as_str())
            {
                next += 1;
            }

            if next - idx > 1 {
                sink.write(&format!("* **{component}:**\n"))?;

                for commit in &section.commits[idx..next] {
                    sink.write(&entry("  * ", "", commit, repository, style))?;
                }
            } else {
                sink.write(&entry(
                    "* ",
                    &format!("**{component}:** "),
                    &section.commits[idx],
                    repository,
                    style,
                ))?;
            }

            idx = next;
        }
    }

    Ok(())
}

/// Builds one bullet line.
///
/// `marker` carries the component marker, or a single space when the commit
/// has no component at all.
fn entry(
    prefix: &str,
    marker: &str,
    commit: &Commit,
    repository: Option<&str>,
    style: LinkStyle,
) -> String {
    let short = &commit.hash[..8];
    let target = style.commit_link(repository, &commit.hash);

    let mut line = format!("{prefix}{marker}{0} ([{short}]({target})", commit.subject);

    append_issues(&mut line, "closes", &commit.closes, repository, style);
    append_breaks(&mut line, commit, repository, style);

    line.push_str(")\n");

    line
}

/// Appends the `Closes #N` references of a commit.
fn append_issues(
    line: &mut String,
    label: &str,
    issues: &Option<Vec<Issue>>,
    repository: Option<&str>,
    style: LinkStyle,
) {
    let Some(issues) = issues else { return };

    for (idx, issue) in issues.iter().enumerate() {
        append_issue(line, label, idx == 0, &issue.issue, repository, style);
    }
}

/// Appends one marker per line of the commit message that mentions a breaking
/// change.
fn append_breaks(line: &mut String, commit: &Commit, repository: Option<&str>, style: LinkStyle) {
    let count = commit
        .body
        .lines()
        .filter(|line| line.contains("BREAKING"))
        .count();

    for idx in 0..count {
        append_issue(line, "breaks", idx == 0, "", repository, style);
    }
}

fn append_issue(
    line: &mut String,
    label: &str,
    first: bool,
    issue: &str,
    repository: Option<&str>,
    style: LinkStyle,
) {
    let target = style.issue_link(repository, issue);

    if target.is_empty() {
        return;
    }

    if first {
        line.push_str(&format!(", {label} [#{issue}]({target})"));
    } else {
        line.push_str(&format!(", [#{issue}]({target})"));
    }
}
