        let aliases = vec!["ft".to_string()];

        assert_eq!(match_subject("ft: one   ", &aliases), Some((None, "one".to_string())));
        assert_eq!(match_subject("ft(sec):\t", &aliases), Some((Some("sec".into()), "".into())));
    }

