        assert_eq!(parse_issues("Closes #2, #3, #4")[0].issue, "4");
        assert_eq!(parse_issues("Closes #2,#3")[0].issue, "2");
        assert_eq!(parse_issues("closes #2").len(), 0);
        assert_eq!(parse_issues("Closes #2\nCloses #9").len(), 2);
        assert_eq!(parse_issues("Closes #2. Closes #3").len(), 1);
        assert_eq!(parse_issues("Closes #2").len(), 1);
