            RawCommit { hash: "c".into(), subject: "ft: three".into(), body: "".into() },
            RawCommit { hash: "d".into(), subject: "ft(sec): four".into(), body: "".into() },
            RawCommit { hash: "e".into(), subject: "unrelated".into(), body: "".into() },
        ];

