        assert_eq!(minor.version.as_deref(), Some("1.3.0"));
        assert!(!minor.patch_version);

        let major = resolve(None, Some(Bump::Major), Some("1.2.3")).unwrap();
        assert_eq!(major.version.as_deref(), Some("2.0.0"));
        assert!(!major.patch_version);
    }

    #[test]
    fn keeps_the_v_prefix_and_extra_parts() {
        assert_eq!(
            resolve(None, Some(Bump::Patch), Some("v1.2.3-alpha.1+meta"))
                .unwrap()
                .version
                .as_deref(),
            Some("v1.2.4-alpha.1+meta")
        );
        assert_eq!(
            resolve(None, Some(Bump::Patch), Some("V1.2.3"))
                .unwrap()
                .version
                .as_deref(),
            Some("v1.2.4")
        );
    }

    #[test]
    fn rejects_invalid_versions() {
        for tag in ["1.2", "1.2.3.4", "01.2.3", "1.2.3-", "abc", "", "1.2.3\n"] {
            assert!(
                resolve(None, Some(Bump::Patch), Some(tag)).is_err(),
                "{tag} should not parse"
            );
        }
    }
}
