cat >> src/link_style.rs <<'EOF'

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn github_and_gitlab_share_the_layout() {
        for style in [LinkStyle::Github, LinkStyle::Gitlab] {
            assert_eq!(
                style.commit_link(Some("https://r/r"), "abcdefgh0123456789"),
                "https://r/r/commit/abcdefgh0123456789"
            );
            assert_eq!(style.issue_link(Some("https://r/r"), "2"), "https://r/r/issues/2");
        }
    }

    #[test]
    fn stash_and_cgit_keep_the_issue_number() {
        assert_eq!(
            LinkStyle::Stash.commit_link(Some("https://r/r"), "abcdefgh0123456789"),
            "https://r/r/commits/abcdefgh0123456789"
        );
        assert_eq!(LinkStyle::Stash.issue_link(Some("https://r/r"), "2"), "2");
        assert_eq!(
            LinkStyle::Cgit.commit_link(Some("https://r/r"), "abcdefgh0123456789"),
            "https://r/r/commit/?id=abcdefgh0123456789"
        );
        assert_eq!(LinkStyle::Cgit.issue_link(Some("https://r/r"), "2"), "2");
    }

    #[test]
    fn without_a_repository_only_the_short_hash_is_used() {
        assert_eq!(
            LinkStyle::Github.commit_link(None, "abcdefgh0123456789"),
            "abcdefgh"
        );
        assert_eq!(LinkStyle::Github.issue_link(None, "2"), "2");
    }

    #[test]
    fn parses_the_link_styles() {
        assert_eq!(parse("github"), Some(LinkStyle::Github));
        assert_eq!(parse("gitlab"), Some(LinkStyle::Gitlab));
        assert_eq!(parse("stash"), Some(LinkStyle::Stash));
        assert_eq!(parse("cgit"), Some(LinkStyle::Cgit));
        assert_eq!(parse("bogus"), None);
    }
}
EOF
