{"command": "cd /workspace && cat >> src/fmt/md_writer.rs <<'EOF'

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fmt::Header;
    use crate::section::{Commit, Issue, RawCommit, build_sections};

    fn header(version: Option<&str>) -> Header {
        Header {
            version: version.map(|v| v.to_string()),
            patch_version: false,
            subtitle: None,
            date: "2020-01-01".to_string(),
        }
    }

    fn commit(component: Option<&str>, subject: &str, hash: &str) -> Commit {
        Commit {
            component: component.map(|c| c.to_string()),
            subject: subject.to_string(),
            hash: hash.to_string(),
            closes: None,
            breaks: None,
            body: String::new(),
        }
    }

    #[test]
    fn renders_header_and_sections() {
        let sections = vec![Section {
            title: "feat".to_string(),
            commits: vec![commit(None, " one", "abcdefgh0123456789")],
        }];

        let out = render(&header(Some("1.0.0")), &sections, None, LinkStyle::Github);

        assert_eq!(
            out,
            "<a name=\"1.0.0\"></a>\n## 1.0.0  (2020-01-01)\n\n\n#### feat\n\n*   one ([abcdefgh](abcdefgh))\n"
        );
    }

    #[test]
    fn patch_versions_use_a_level_three_header() {
        let mut hdr = header(Some("1.0.1"));
        hdr.patch_version = true;

        let out = render(&hdr, &[], None, LinkStyle::Github);

        assert!(out.starts_with("<a name=\"1.0.1\"></a>\n### 1.0.1  (2020-01-01)\n"));
    }

    #[test]
    fn groups_commits_sharing_a_component() {
        let sections = vec![Section {
            title: "feat".to_string(),
            commits: vec![
                commit(Some("core"), " one", "abcdefgh0123456789"),
                commit(Some("core"), " two", "ijklmnop0123456789"),
                commit(Some("ui"), " three", "qrstuvwx0123456789"),
            ],
        }];

        let out = render(&header(Some("1.0.0")), &sections, None, LinkStyle::Github);

        assert_eq!(
            out,
            "<a name=\"1.0.0\"></a>\n## 1.0.0  (2020-01-01)\n\n\n#### feat\n\n* **core:**\n  *  one ([abcdefgh](abcdefgh))\n  *  two ([ijklmnop](ijklmnop))\n* **ui:**  three ([qrstuvwx](qrstuvwx))\n"
        );
    }

    #[test]
    fn renders_closes_and_breaks() {
        let mut one = commit(Some("db"), " t", "abcdefgh0123456789");
        one.closes = Some(vec![Issue { issue: "5".into(), issue_link: "5".into() }]);
        one.breaks = Some(vec![Issue { issue: "5".into(), issue_link: "5".into() }]);
        one.body = "BREAKING CHANGE: Closes #5".to_string();

        let sections = vec![Section { title: "perf".to_string(), commits: vec![one] }];
        let out = render(
            &header(Some("1.0.0")),
            &sections,
            Some("https://r/r"),
            LinkStyle::Github,
        );

        assert!(out.ends_with(
            "* **db:**  t ([abcdefgh](https://r/r/commit/abcdefgh0123456789), closes [#5](https://r/r/issues/5), breaks [#](https://r/r/issues/))\n"
        ));
    }

    #[test]
    fn end_to_end_section_building() {
        let aliases = vec![("feat".to_string(), vec!["ft".to_string()])];
        let commits = vec![RawCommit {
            hash: "abcdefgh0123456789".to_string(),
            subject: "ft(core): one".to_string(),
            body: "Closes #2".to_string(),
        }];

        let sections = build_sections(&commits, &aliases);
        let out = render(&header(Some("1.0.0")), &sections, None, LinkStyle::Github);

        assert_eq!(
            out,
            "<a name=\"1.0.0\"></a>\n## 1.0.0  (2020-01-01)\n\n\n#### feat\n\n* **core:**  one ([abcdefgh](abcdefgh), closes [#2](2))\n"
        );
    }
}
EOF
