#[cfg(test)]
mod tests {
    use super::*;

    fn write_config(contents: &str) -> String {
        let dir = std::env::temp_dir().join(format!("clog-test-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("config.toml");
        std::fs::write(&path, contents).unwrap();
        path.to_string_lossy().into_owned()
    }

    #[test]
    fn parses_the_clog_table_and_sections() {
        let path = write_config(
            "[clog]\nrepository = \"https://r/r\"\nfrom-latest-tag = true\n\n[sections]\nfeat = [\"ft\"]\n",
        );

        let config = ClogToml::from_path(&path).expect("valid configuration");

        assert_eq!(config.clog.repository.as_deref(), Some("https://r/r"));
        assert_eq!(config.clog.from_latest_tag, Some(true));
        assert_eq!(
            config.sections().unwrap(),
            vec![("feat".to_string(), vec!["ft".to_string()])]
        );
    }

    #[test]
    fn sections_keep_their_declaration_order() {
        let path = write_config(
            "[clog]\n\n[sections]\nzzz = [\"z\"]\naaa = [\"a\"]\nfeat = [\"ft\"]\n",
        );

        let config = ClogToml::from_path(&path).unwrap();

        let titles: Vec<String> = config
            .sections()
            .unwrap()
            .into_iter()
            .map(|(title, _)| title)
            .collect();

        assert_eq!(titles, vec!["zzz", "aaa", "feat"]);
    }

    #[test]
    fn unknown_keys_are_ignored() {
        let path = write_config("[clog]\nfoo = 1\nbar = \"x\"\n");

        let config = ClogToml::from_path(&path).unwrap();

        assert_eq!(config.clog.repository, None);
        assert!(config.sections().unwrap().is_empty());
    }

    #[test]
    fn the_clog_table_is_required() {
        let path = write_config("foo = 1\n");

        assert_eq!(ClogToml::from_path(&path), Err(crate::errors::Error::Toml));
    }

    #[test]
    fn wrong_types_are_rejected() {
        for contents in [
            "[clog]\nrepository = 5\n",
            "[clog]\nfrom-latest-tag = \"yes\"\n",
            "[clog]\nlink-style = \"bogus\"\n",
            "[clog]\n\n[sections]\nfeat = \"notarray\"\n",
            "not toml {{{\n",
        ] {
            let path = write_config(contents);

            assert_eq!(
                ClogToml::from_path(&path),
                Err(crate::errors::Error::Toml),
                "{contents} should not parse"
            );
        }
    }

    #[test]
    fn missing_file_is_an_io_error() {
        assert_eq!(
            ClogToml::from_path("/nonexistent/clog/config.toml"),
            Err(crate::errors::Error::Io)
        );
    }
}
EOF
